def solve_bfs(gi):
    # BFS from all seeds simultaneously through 0-cells (not 1-walls); paint first-reach color; walls stay 1
    g=[row[:] for row in gi]; H,W=len(gi),len(gi[0])
    dist=[[999]*W for _ in range(H)]; par=[[-1]*W for _ in range(H)]
    dq=deque()
    for a in range(H):
        for b in range(W):
            v=gi[a][b]
            if v not in (0,1):
                dist[a][b]=0; par[a][b]=v; dq.append((a,b))
    while dq:
        a,b=dq.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+dx,b+dy
            if 0<=x<H and 0<=y<W and gi[x][y]==0 and dist[x][y]>dist[a][b]+1:
                dist[x][y]=dist[a][b]+1; par[x][y]=par[a][b]; dq.append((x,y))
    out=[row[:] for row in gi]
    for a in range(H):
        for b in range(W):
            if gi[a][b]==0: out[a][b]=par[a][b]
    return out
